import { SignIn } from '@clerk/clerk-react';

export default function LoginPage() {
  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100">
      <SignIn 
        routing="path" 
        path="/login" 
        signUpUrl="/signup"
        forceRedirectUrl="/dashboard" 
      />
    </div>
  );
}
